@spec tracker_page_spec  src=tests/specs/tracker_page_spec.lua  loc=1631  cases=50
@exercises tuning (tuning), configManager (h.cm), commandManager (h.cmgr), midiManager (h.mm), trackerManager (h.tm)
@surface   tuning.derive, tuning.genDiamond, cm:setContext, cmgr:push, cmgr:invoke, cm:getAt, cm:set, cm:get, tuning.stepToMidi, mm:subscribe, mm:notes, tm:assignEvent, tm:byUuid, tm:flush
@harness   mk, reaper:addItem, reaper:setProjectTracks, reaper:seedMidi

# Intent
  Pin-tests for trackerPage's Page interface (bind / unbind / focusState /
  bind-from-cursor) and the retune modal's slots, defaults and dispatch.
  render / handleInput are stubs wired in step 3 and verified in REAPER, not here.

# Helpers
  @fn resetArrange()  @ 59-163
  @fn seedItems(h, takes, srcLen)  @ 179-184
      -- A bind re-keys cm's track tier off the take's own item, so a take named in
      -- fakeArrange needs one in the fake project too.
  @fn newTrackerPage(cm, ds, cmgr, chrome, gui)  @ 186-195
  @fn trackList(trackCount)  @ 197-203
  @fn mapTracker(harness, inst, trackCount)  @ 208-222
      -- A tracker bound to the take 'i0' over a track list of the given width, with
      -- i0's placement as the caller states it; inst = nil binds it into no instance.
      -- Returns the page's tv, and the harness behind it for the cmgr.

# Cases
  @case 'bind(take) drives cm:setContext via the page's own tm:bindTake'  [harness]  @ 226-234
  @case 'unbind() drives cm:setContext(nil) via the page's own tm:bindTake'  [harness]  @ 237-246
  @case 'focusState before any render returns both bits false'  [harness]  @ 249-256
  @case 'bindFromSelection binds tm to the resolved selection take, drops when the track has no slots'  [harness]  @ 262-275
  @case 'with no live instance, the new take mints a parked slot and selects it'  [harness]  @ 279-296
  @case 'deleteBoundSlot confirms, then deletes the bound slot through the arrange facade'  [harness]  @ 302-323
  @case 'take properties renames the bound take\'s slot, not that one take'  [harness]  @ 329-347
  @case 'take properties follows the bound take when the tracker sits on another slot'  [harness]  @ 354-372
  @case 'the new take places below the current instance and becomes current'  [harness]  @ 378-411
  @case 'a new take on a just-selected track parks, rather than appending on the old one'  [harness]  @ 415-439
  @case 'duplicate below appends another instance of the bound slot and makes it current'  [harness]  @ 445-475
  @case 'duplicate below refuses where the free span falls short'  [harness]  @ 479-500
  @case 'duplicate below on a slot whose only take is parked does nothing'  [harness]  @ 504-517
  @case 'the variant step rebinds the tracker to the slot stepped to and follows its placement'  [harness]  @ 523-557
  @case 'a variant step with the tracker in no instance does nothing'  [harness]  @ 561-575
  @case 'prev/next track + take drive the tv selection, not the arrange cursor'  [harness]  @ 579-602
  @case 'a track step lands on the placement overlapping the current instance most'  [harness]  @ 606-642
  @case 'with nothing overlapping, a track step lands on the placement nearest in time'  [harness]  @ 646-681
  @case 'F6 plays from the instance dived into, not the placement the bind resolved'  [harness]  @ 688-705
  @case 'a dive outranks a play head already sitting in another instance'  [harness]  @ 709-732
  @case 'the play head entering an instance makes it current; leaving one writes nothing'  [harness]  @ 736-759
  @case 'a slot change seeks from the outgoing instance, backwards for prevTake'  [harness]  @ 763-798
  @case 'the walk steps along the track's placements in start order, holding at the ends'  [harness]  @ 802-850
  @case 'a walk into another slot resets the caret; within one slot the caret holds'  [harness]  @ 854-891
  @case 'deleting the instance drops that placement and lands on the one before it'  [harness]  @ 895-929
  @case 'a slot with no live instance leaves the tracker nowhere, and F6 silent'  [harness]  @ 933-949
  @case 'the map window centres the bound column, and clamps it at both ends'  [harness]  @ 958-976
  @case 'the map window pages time, a start in the last bar opening the next page'  [harness]  @ 980-996
  @case 'with the tracker in no instance the map window pages on the edit cursor'  [harness]  @ 1000-1007
  @case 'the map window carries the takes over it, the current instance marked'  [harness]  @ 1011-1022
  @case 'the map window carries the transport it meets, and only that'  [harness]  @ 1026-1049
  @case 'the pin key holds the map up as the palette default, and drops it when pressed again'  [harness]  @ 1053-1062
  @case 'a gesture raises the map, and it falls at the next command'  [harness]  @ 1066-1107
  @case 'the play row is the head\'s offset into the current instance, in rows'  [harness]  @ 1111-1138
  @case 'the play row dims where the head is sounding a sibling instance'  [harness]  @ 1142-1166
  @case 'the cut row is where the rendered span stops short of the source'  [harness]  @ 1173-1194
  @case 'the play row and the head row count from the source origin, not the start'  [harness]  @ 1200-1224
  @case 'a dive carries the arrange QN to the caret row, and the caret hands it back'  [harness]  @ 1231-1250
  @case 'a caret outside the rendered span hands back the row the span stops at'  [harness]  @ 1254-1273
  @case 'leaving the tracker puts the arrange caret where the tracker caret is'  [harness]  @ 1277-1299
  @case 'with loop to item on, a dive brackets the instance dived into'  [harness]  @ 1305-1323
  @case 'the play head entering an instance leaves the loop where it was'  [harness]  @ 1327-1345
  @case 'the toggle command brackets the current instance as it comes on'  [harness]  @ 1349-1371
  @case 'the loop-to-item verb brackets the current instance, toggle or no toggle'  [harness]  @ 1375-1399
  @case 'retune opens on the scope the selection implies and OK snaps that scope'  [harness]  @ 1405-1460
  @case 'retune opens on the facility the take carries, its dials on their figures'  [harness]  @ 1468-1497
  @case 'a refused retune offers to widen, and the offer taken solves again'  [harness]  @ 1503-1546
  @case 'empty grid shows the single no-takes message'  [harness]  @ 1552-1566
  @case 'an owned tm flush resyncs the watcher baseline; only a foreign write trips the reload'  [harness]  @ 1573-1605
  @case 'bindFromSelection re-keys cm on return from dormancy even when the take is unchanged'  [harness]  @ 1609-1629

